insert into public.categories (slug, name_en, name_ar, sort, is_active, blurb_en, blurb_ar, image) values
 ('perfumes','Perfumes','العطور',60,false,'Ahmed Al Maghribi eau de parfum, hair mists and fragrance gift sets.','عطور أحمد المغربي ومعطرات الشعر ومجموعات الهدايا العطرية.','/products/aam/marj-60-ml-1.jpg'),
 ('oud-oils','Oud and Perfume Oils','دهن العود والعطور الزيتية',70,false,'Dehn al oud and concentrated perfume oils by Ahmed Al Maghribi, applied by hand.','دهن العود والعطور الزيتية المركزة من أحمد المغربي.','/products/aam/dehn-al-oud-maliki-qadeem-1.jpg'),
 ('bakhoor','Bakhoor and Oud','البخور والعود',80,false,'Bakhoor tablets and scented oud wood by Ahmed Al Maghribi, for the mabkhara.','أقراص البخور والعود المعطر من أحمد المغربي للمبخرة.','/products/aam/bakhoor-ahmed-20-tabs-1.jpg')
